// ─── Universal Icon Component ────────────────────────────────────────────────

export const Icon: React.FC<IconProps> = ({ name, ...props }) => {
  if (!name) return null;
  const Component = SVG_ICONS[name];
  if (!Component) {
    console.warn(`Icon "${name}" not found in SVG icon library.`);
    return null;
  }
  return <Component {...props} />;
};

export default Icon;
